TITLE: Handle Middleware Request with URLPattern
DESCRIPTION: This TypeScript code provides a corrected approach for handling Next.js middleware requests by utilizing `URLPattern` to extract `locale` and `slug` parameters from the request URL. It defines a `params` helper function to parse the URL based on predefined patterns and then redirects the request to a new URL. This method replaces the deprecated `request.page` functionality.

SOURCE: https://github.com/vercel/next.js/blob/canary/errors/middleware-request-page.mdx#_snippet_1

LANGUAGE: ts
CODE:
```
import { NextRequest, NextResponse } from 'next/server'

const PATTERNS = [
  [
    new URLPattern({ pathname: '/:locale/:slug' }),
    ({ pathname }) => pathname.groups,
  ],
]

const params = (url) => {
  const input = url.split('?')[0]
  let result = {}

  for (const [pattern, handler] of PATTERNS) {
    const patternResult = pattern.exec(input)
    if (patternResult !== null && 'pathname' in patternResult) {
      result = handler(patternResult)
      break
    }
  }
  return result
}

export function middleware(request: NextRequest) {
  const { locale, slug } = params(request.url)

  if (locale && slug) {
    const { search, protocol, host } = request.nextUrl
    const url = new URL(`${protocol}//${locale}.${host}/${slug}${search}`)
    return NextResponse.redirect(url)
  }
}
```

