Here's the code to generate the summary of Central Park's features:

```javascript
const centralParkData = {
  // Insert the full JSON data here
};

const features = centralParkData.features;
const summary = {};

for (const category in features) {
    const categoryFeatures = features[category];
    const featureCount = categoryFeatures.length;

    const tagCounts = {};
    for (const feature of categoryFeatures) {
        const tags = feature.tags;
        for (const tagKey in tags) {
            tagCounts[tagKey] = (tagCounts[tagKey] || 0) + 1;
        }
    }

    const sortedTags = Object.entries(tagCounts)
        .map(([tag, count]) => ({ tag, count }))
        .sort((a, b) => b.count - a.count);

    const topTags = sortedTags.slice(0, 3);

    summary[category] = {
        feature_count: featureCount,
        top_tags: topTags
    };
}

console.log(JSON.stringify(summary, null, 2));
```

